     * Timer clock = PCLK2 = 170 MHz (APB2 prescaler = 1).
     * Counter frequency = 170 MHz / (PSC + 1) = 170 MHz (PSC = 0).
     * PWM period = 170,000,000 Hz / 20,000 Hz = 8,500 timer ticks.
     * ARR = Period - 1 = 8500 - 1 = 8499.
     * CCR1 = 8500 * 25% = 2125 ticks.
     */
    TIM1->PSC  = 0U;
    TIM1->ARR  = 8500U - 1U;
    TIM1->CCR1 = 2125U;

    /* 4. Configure Channel 1: PWM Mode 1 (OC1M = 0110b), enable OC1 preload [STM32G474_RM0440 p.1265] */
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 5. Set output polarity to active-high (CC1P = 0) and enable output (CC1E = 1) [STM32G474_RM0440 p.1265] */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 6. Advanced-control timer: Enable Main Output (MOE) [STM32G474_RM0440 p.1265] */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Enable ARR preload and generate an update event to latch ARR, PSC, and CCR1 into shadow registers */
    TIM1->CR1 |= TIM_CR1_ARPE;
    TIM1->EGR  = TIM_EGR_UG;

    /* 7. Start the counter (CEN = 1) [STM32G474_RM0440 p.1265] */
    TIM1->CR1 |= TIM_CR1_CEN;
